import { createSlice } from '@reduxjs/toolkit';
const postsSlice = createSlice({
  name: 'posts',
  initialState: { loading: false, items: [], error: null },
  reducers: {
    loading: (state) => { state.loading = true; state.error = null; },
    success: (state, action) => {
      state.loading = false; state.items = action.payload;
    },
    error: (state, action) => {
      state.loading = false; state.error = action.payload;
    },
  },
});
export default postsSlice.reducer;

// thunk: action creator trả về một hàm (dispatch) => { ... }
export const fetchPosts = () => async (dispatch) => {
  dispatch({ type: 'posts/loading' });
  try {
    const res = await axios.get('https://jsonplaceholder.typicode.com/posts');
    dispatch({ type: 'posts/success', payload: res.data });
  } catch (e) {
    dispatch({ type: 'posts/error', payload: e.message });
  }
};

