export function cartReducer(cart, action) {
  switch (action.type) {
    case "add": {
      const co = cart.find((x) => x.id === action.sp.id);
      if (co) {
        return cart.map((x) =>
          x.id === action.sp.id ? { ...x, sl: x.sl + 1 } : x);
      }
      return [...cart, { ...action.sp, sl: 1 }];
    }
    case "remove":
      return cart.filter((x) => x.id !== action.id);
    case "clear":
      return [];
    default:
      return cart;
  }
}

